PRAGMA foreign_keys=OFF;
CREATE TABLE alerts (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp TEXT NOT NULL,
                    severity TEXT NOT NULL,
                    module TEXT NOT NULL,
                    title TEXT NOT NULL,
                    description TEXT,
                    file_path TEXT,
                    process_info TEXT,
                    ip_address TEXT,
                    reason TEXT,
                    evidence TEXT,
                    resolved INTEGER DEFAULT 0,
                    is_self_test INTEGER DEFAULT 0,
                    source TEXT DEFAULT 'engine',
                    created_at TEXT DEFAULT (datetime('now'))
                );
CREATE TABLE file_hashes (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    file_path TEXT UNIQUE NOT NULL,
                    hash_value TEXT NOT NULL,
                    file_size INTEGER,
                    last_seen TEXT NOT NULL,
                    first_seen TEXT NOT NULL,
                    modified_count INTEGER DEFAULT 0
                );
CREATE TABLE processes (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp TEXT NOT NULL,
                    pid INTEGER NOT NULL,
                    name TEXT NOT NULL,
                    cmdline TEXT,
                    parent_pid INTEGER,
                    parent_name TEXT,
                    username TEXT,
                    status TEXT,
                    is_suspicious INTEGER DEFAULT 0,
                    reason TEXT
                );
CREATE TABLE network_events (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp TEXT NOT NULL,
                    local_addr TEXT,
                    local_port INTEGER,
                    remote_addr TEXT,
                    remote_port INTEGER,
                    protocol TEXT,
                    status TEXT,
                    pid INTEGER,
                    process_name TEXT,
                    is_suspicious INTEGER DEFAULT 0,
                    reason TEXT
                );
CREATE TABLE quarantined_files (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    original_path TEXT NOT NULL,
                    quarantine_path TEXT NOT NULL,
                    timestamp TEXT NOT NULL,
                    reason TEXT,
                    file_hash TEXT,
                    file_size INTEGER,
                    restored INTEGER DEFAULT 0
                );
CREATE TABLE waf_events (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp TEXT NOT NULL,
                    ip_address TEXT,
                    method TEXT,
                    path TEXT,
                    query_string TEXT,
                    user_agent TEXT,
                    attack_type TEXT,
                    pattern_matched TEXT,
                    blocked INTEGER DEFAULT 1,
                    country TEXT,
                    abuse_score INTEGER
                );
CREATE TABLE traffic_log (
                    ip_address TEXT PRIMARY KEY,
                    hit_count INTEGER DEFAULT 1,
                    first_seen TEXT NOT NULL,
                    last_seen TEXT NOT NULL,
                    is_blocked INTEGER DEFAULT 0,
                    country TEXT,
                    abuse_score INTEGER,
                    last_notes TEXT
                );
CREATE TABLE login_attempts (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    ip_address TEXT NOT NULL,
                    timestamp TEXT NOT NULL,
                    success INTEGER DEFAULT 0
                );
CREATE TABLE silences (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    type TEXT NOT NULL,
                    value TEXT NOT NULL,
                    created_at TEXT DEFAULT (datetime('now')),
                    UNIQUE(type, value)
                );
CREATE TABLE alert_explanations (
                    alert_id INTEGER PRIMARY KEY,
                    explanation TEXT NOT NULL,
                    model TEXT NOT NULL,
                    created_at TEXT DEFAULT (datetime('now')),
                    FOREIGN KEY (alert_id) REFERENCES alerts(id)
                );
CREATE TABLE fp_scores (
                    alert_id INTEGER PRIMARY KEY,
                    score REAL NOT NULL,
                    verdict TEXT NOT NULL,
                    factors TEXT,
                    created_at TEXT DEFAULT (datetime('now')),
                    FOREIGN KEY (alert_id) REFERENCES alerts(id)
                );
CREATE TABLE alert_rules (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    severity TEXT,
                    module TEXT,
                    pattern TEXT,
                    webhook_url TEXT NOT NULL,
                    enabled INTEGER DEFAULT 1,
                    created_at TEXT DEFAULT (datetime('now')),
                    updated_at TEXT DEFAULT (datetime('now'))
                );
CREATE TABLE api_keys (
                    service TEXT PRIMARY KEY,
                    api_key TEXT NOT NULL,
                    updated_at TEXT DEFAULT (datetime('now'))
                );
CREATE TABLE login_events (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp TEXT NOT NULL,
                    source_ip TEXT,
                    username TEXT,
                    service TEXT NOT NULL,
                    status TEXT NOT NULL,
                    port INTEGER,
                    log_source TEXT,
                    geo_country TEXT,
                    abuse_score INTEGER,
                    created_at TEXT DEFAULT (datetime('now'))
                );
CREATE TABLE waf_custom_rules (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    description TEXT DEFAULT '',
                    attack_type TEXT NOT NULL DEFAULT 'custom',
                    severity TEXT NOT NULL DEFAULT 'medium',
                    pattern TEXT NOT NULL,
                    action TEXT NOT NULL DEFAULT 'block',
                    enabled INTEGER NOT NULL DEFAULT 1,
                    is_default INTEGER NOT NULL DEFAULT 0,
                    created_at TEXT DEFAULT (datetime('now'))
                );
CREATE INDEX idx_alerts_timestamp ON alerts(timestamp);
CREATE INDEX idx_alerts_severity ON alerts(severity);
CREATE INDEX idx_alerts_dedup ON alerts(title, ip_address, module, timestamp);
CREATE INDEX idx_file_hashes_path ON file_hashes(file_path);
CREATE INDEX idx_network_remote ON network_events(remote_addr);
CREATE INDEX idx_login_attempts_ip ON login_attempts(ip_address, timestamp);
CREATE INDEX idx_login_events_ip ON login_events(source_ip);
CREATE INDEX idx_login_events_service ON login_events(service);
CREATE INDEX idx_login_events_timestamp ON login_events(timestamp);
