INSERT INTO waf_custom_rules VALUES(1,'Default: UNION SELECT statement','UNION SELECT statement','sqli','critical','(?i)\bunion\b.{0,30}\bselect\b','block',1,1,'2026-07-03 06:48:04');
INSERT INTO waf_custom_rules VALUES(2,'Default: SQL comment injection','SQL comment injection','sqli','critical','(?:--|#|/\*|\*/)','block',1,1,'2026-07-03 06:48:04');
INSERT INTO waf_custom_rules VALUES(3,'Default: SQL boolean injection','SQL boolean injection','sqli','high','(?i)\b(?:and|or)\b\s+\d+\s*[=<>]','block',1,1,'2026-07-03 06:48:04');
INSERT INTO waf_custom_rules VALUES(4,'Default: SQL single-quote injection','SQL single-quote injection','sqli','high','''(?:\s*;|\s+or|\s+and|\s+union)','block',1,1,'2026-07-03 06:48:04');
INSERT INTO waf_custom_rules VALUES(5,'Default: SQL DROP/INSERT/UPDATE','SQL DROP/INSERT/UPDATE','sqli','high','(?i)\b(?:drop|insert|update|delete|truncate|alter|create|exec|execute)\b','block',1,1,'2026-07-03 06:48:04');
INSERT INTO waf_custom_rules VALUES(6,'Default: Stacked SQL queries','Stacked SQL queries','sqli','critical','(?i);\s*(?:drop|delete|insert|update|exec|declare|select)\s','block',1,1,'2026-07-03 06:48:04');
INSERT INTO waf_custom_rules VALUES(7,'Default: Time-based blind SQL (SLEEP/BENCHMARK)','Time-based blind SQL (SLEEP/BENCHMARK)','sqli','high','(?i)\b(?:sleeper\(\s*\d|benchmark\(\s*\d+|pg_sleep|waitfor\s+delay|wait\s+time\s+for)\s*\(','block',1,1,'2026-07-03 06:48:04');
INSERT INTO waf_custom_rules VALUES(8,'Default: SQL hex/char encoding bypass','SQL hex/char encoding bypass','sqli','high','(?i)0x[0-9a-f]{4,}|char\(\d+|nchar\(\d+|unhex\(|uncompress\(','block',1,1,'2026-07-03 06:48:04');
INSERT INTO waf_custom_rules VALUES(9,'Default: SQL information_schema access','SQL information_schema access','sqli','high','(?i)information_schema|sys\.(?:tables|columns)|sqlite_master|mysql\.(?:user|db)','block',1,1,'2026-07-03 06:48:04');
INSERT INTO waf_custom_rules VALUES(10,'Default: SQL INTO OUTFILE/DUMPFILE','SQL INTO OUTFILE/DUMPFILE','sqli','high','(?i)\binto\s+(?:outfile|dumpfile)\s+','block',1,1,'2026-07-03 06:48:04');
INSERT INTO waf_custom_rules VALUES(11,'Default: SQL large object access (pg_largeobject)','SQL large object access (pg_largeobject)','sqli','critical','(?i)pg_largeobject|lo_import|lo_export|pg_read_file','block',1,1,'2026-07-03 06:48:04');
INSERT INTO waf_custom_rules VALUES(12,'Default: SQL CONCAT/GROUP_CONCAT enumeration','SQL CONCAT/GROUP_CONCAT enumeration','sqli','high','(?i)(?:group_concat|concat_ws|string_agg|listagg)\s*\(','block',1,1,'2026-07-03 06:48:04');
INSERT INTO waf_custom_rules VALUES(13,'Default: SQL UPDATE/INSERT with subquery','SQL UPDATE/INSERT with subquery','sqli','high','(?i)(?:update|insert)\s+\w+\s+set\s+\w+\s*=\s*\(select','block',1,1,'2026-07-03 06:48:04');
INSERT INTO waf_custom_rules VALUES(14,'Default: SQL ORDER BY numeric (column brute)','SQL ORDER BY numeric (column brute)','sqli','high','(?i)\border\s+by\s+\d{2,}','block',1,1,'2026-07-03 06:48:04');
INSERT INTO waf_custom_rules VALUES(15,'Default: SQL HAVING/RAND (blind probing)','SQL HAVING/RAND (blind probing)','sqli','high','(?i)\bhaving\s+\d+|order\s+by\s+rand\(\)|group\s+by\s+rand\(','block',1,1,'2026-07-03 06:48:04');
INSERT INTO waf_custom_rules VALUES(16,'Default: Script tag injection','Script tag injection','xss','high','(?i)<\s*script[^>]*>','block',1,1,'2026-07-03 06:48:04');
INSERT INTO waf_custom_rules VALUES(17,'Default: JavaScript event handler','JavaScript event handler','xss','high','(?i)\bon(?:load|click|error|mouseover|focus|blur|key|submit|unload|change|resize|scroll|wheel|drag|drop|contextmenu)\s*=','block',1,1,'2026-07-03 06:48:04');
INSERT INTO waf_custom_rules VALUES(18,'Default: JavaScript URI scheme','JavaScript URI scheme','xss','medium','(?i)javascript\s*:','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(19,'Default: Data URI with HTML','Data URI with HTML','xss','medium','(?i)data\s*:\s*text/html','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(20,'Default: XSS via <svg> with onload','XSS via <svg> with onload','xss','high','(?i)<svg[^>]*onload\s*=','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(21,'Default: XSS via <body/input/details> onload/onfocus','XSS via <body/input/details> onload/onfocus','xss','high','(?i)<(?:body|details|select|textarea|marquee)\s+[^>]*onfocus\s*=','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(22,'Default: XSS via <img> with onerror/onload','XSS via <img> with onerror/onload','xss','high','(?i)<\s*img[^>]*(?:onerror|onload)\s*=','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(23,'Default: XSS via <link> with onerror/onload','XSS via <link> with onerror/onload','xss','high','(?i)<\s*link[^>]*(?:onerror|onload)\s*=','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(24,'Default: XSS via <math> with xlink:href','XSS via <math> with xlink:href','xss','medium','(?i)<math[^>]*xlink\s*:','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(25,'Default: XSS polyglot injection','XSS polyglot injection','xss','high','(?i)\"'';?\s*--[^>]*>[^<]*(?:<|<)/?\s*(?:script|svg|img|body)','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(26,'Default: XSS via CSS expression/url','XSS via CSS expression/url','xss','high','(?i)expression\s*\(|url\s*\(\s*[''\"]?\s*javascript','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(27,'Default: XSS via iframe srcdoc','XSS via iframe srcdoc','xss','high','(?i)<\s*iframe[^>]*srcdoc\s*=','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(28,'Default: XSS via object/data/base tags','XSS via object/data/base tags','xss','medium','(?i)<\s*(?:object|embed|applet)\s+[^>]*data\s*=|<base\s+href\s*=\s*https?://','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(29,'Default: XSS via formaction/autofocus','XSS via formaction/autofocus','xss','medium','(?i)formaction\s*=|autofocus\s*=|onpointer(?:enter|leave|over|out)\s*=','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(30,'Default: DOM clobbering via id/name','DOM clobbering via id/name','xss','medium','(?i)<\s*(?:a|span|div)\s+[^>]*id\s*=\s*[''\"]?(?:innerHTML|value|then|location|cookie)','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(31,'Default: Mutation XSS (mXSS) bypass patterns','Mutation XSS (mXSS) bypass patterns','xss','high','(?i)<(?:noscript|style|title|textarea|listing|xmp)\s*>.*<','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(32,'Default: XSS via import and behavior','XSS via import and behavior','xss','high','(?i)(?:behavior|import)\s*:\s*u?r?l|<?\s*import\s+implementation','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(33,'Default: XSS via angular template injection','XSS via angular template injection','xss','high','(?i)\{\{.*\}.*\}.*\}|(\{.*\}).*constructor|ng-init\s*=|ng-csp\s*=','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(34,'Default: XSS via meta refresh/redirect','XSS via meta refresh/redirect','xss','medium','(?i)<\s*meta[^>]*http-equiv\s*=\s*[''\"]?\s*refresh','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(35,'Default: XSS via WebSocket constructor','XSS via WebSocket constructor','xss','high','(?i)new\s+WebSocket\s*\(\s*[''\"]ws[^s]','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(36,'Default: XSS via postMessage/importScripts','XSS via postMessage/importScripts','xss','high','(?i)(?:postMessage|importScripts|importScripts)\s*\([^)]*[''\"]','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(37,'Default: JavaScript global storage access','JavaScript global storage access','xss','high','(?i)globalStorage\s*\[|localStorage\s*\[|sessionStorage\s*\[','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(38,'Default: Directory traversal sequence','Directory traversal sequence','traversal','high','\.\./|\.\.\\','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(39,'Default: Encoded traversal (double)','Encoded traversal (double)','traversal','high','%2e%2e%2f|%2e%2e/|\.\.%2f|%%32%65|%%32%45|%%32%46','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(40,'Default: Unicode/UTF-8 overlong traversal','Unicode/UTF-8 overlong traversal','traversal','high','%c0%ae%c0%ae|%c0%2e%c0%2e|%252e%252e%252f','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(41,'Default: Absolute path attempt','Absolute path attempt','traversal','medium','(?:/etc/(?:passwd|shadow|hosts|group|sudoers|ssh)|/proc/self|/boot/|/sys/)','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(42,'Default: Null byte injection (path truncation)','Null byte injection (path truncation)','traversal','high','%00|%0d%0a.*(?:\.\./|\.\.\\)','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(43,'Default: env/;/proc/self/environ access','env/;/proc/self/environ access','traversal','high','/proc/self/(?:environ|fd/\d+|cmdline|maps)','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(44,'Default: Windows system path traversal','Windows system path traversal','traversal','high','[a-zA-Z]:\\\\(?:windows|winnt|boot|system32|program)','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(45,'Default: .htaccess/.git/config exposure','.htaccess/.git/config exposure','traversal','medium','(?:\.htaccess|\.git/config|\.svn/entries|\.DS_Store)','block',1,1,'2026-07-03 06:48:05');
INSERT INTO waf_custom_rules VALUES(46,'Default: WEB-INF/web.xml exposure','WEB-INF/web.xml exposure','traversal','high','WEB-INF/(?:web|database)\.xml|META-INF/MANIFEST\.MF','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(47,'Default: Alternate data stream (NTFS ADS)','Alternate data stream (NTFS ADS)','traversal','medium',':[a-zA-Z]+:\$DATA','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(48,'Default: Shell command chaining (wget/curl)','Shell command chaining (wget/curl)','cmdi','critical',';\s*(?:wget|curl)\s+https?://','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(49,'Default: Command substitution (backtick/dollar)','Command substitution (backtick/dollar)','cmdi','critical','`[^`]+`|\$\([^)]+\)','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(50,'Default: Pipe to shell interpreter','Pipe to shell interpreter','cmdi','high','\|\s*(?:bash|sh|cmd|powershell|zsh|dash|fish|ksh)','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(51,'Default: Semicolon command separator','Semicolon command separator','cmdi','high',';\s*(?:id|whoami|uname|cat\s+/etc|ls\s+-la|pwd|hostname|ifconfig|ip\s+addr)','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(52,'Default: Blind/out-of-band command exfiltration','Blind/out-of-band command exfiltration','cmdi','critical','(?i)(?:nslookup|dig|ping|nc|netcat)\s+(?:-c\s+)?https?://','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(53,'Default: Base64-encoded command execution','Base64-encoded command execution','cmdi','critical','(?i)(?:echo|printf)\s+[''\"]?[a-z0-9+/]{20,}={0,2}\s*\|(?:\s*)base64\s*-d\s*\|','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(54,'Default: Environment variable expansion in args','Environment variable expansion in args','cmdi','high','\$\{env:|%\w+%\}|\$\{PATH\}|\$\{HOME\}','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(55,'Default: Newline-separated command injection','Newline-separated command injection','cmdi','high','\n\s*(?:id|whoami|cat|wget|curl|nc|bash|sh|python)','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(56,'Default: Tcl exec injection','Tcl exec injection','cmdi','high','(?:exec\s+|eval\s+)\s*(?:id|whoami|cat|ls|wget)','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(57,'Default: AWK/sed/perl one-liner execution','AWK/sed/perl one-liner execution','cmdi','high','(?i)(?:awk|sed|perl|ruby|python)\s+-[a-z]{1,2}\s*[''\"].*(?:system|exec|backtick|`|system\(|exec\()','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(58,'Default: XARGS/LD_PRELOAD exploitation','XARGS/LD_PRELOAD exploitation','cmdi','high','(?i)(?:xargs\s+-I|xargs\s+-0|LD_PRELOAD\s*=|IFS\s*=)','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(59,'Default: Command redirection to file','Command redirection to file','cmdi','high','>\s*(?:/dev/(?:tcp|udp)|/tmp/|/var/tmp/|/dev/shm/)','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(60,'Default: PHP wrapper inclusion (php://)','PHP wrapper inclusion (php://)','lfi','critical','(?i)php://(?:input|filter|data|stdin|output|memory|temp|fd)','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(61,'Default: PHP wrapper with base64 decode','PHP wrapper with base64 decode','lfi','critical','(?i)php://filter/.*base64-encode|php://filter/.*convert\.','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(62,'Default: Remote file inclusion','Remote file inclusion','lfi','high','(?i)(?:include|require)(?:_once)?\s*\(?\s*[''\"]?https?://','block',1,1,'2026-07-03 06:48:06');
