INSERT INTO waf_custom_rules VALUES(64,'Default: Log file injection (poisoning)','Log file injection (poisoning)','lfi','high','(?:/var/log/(?:apache2?|nginx|httpd|auth|syslog)|C:\\xampp\\apache\\logs)','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(65,'Default: Phar deserialization wrapper','Phar deserialization wrapper','lfi','high','(?i)phar://|compress\.(?:zlib|bzip2)://','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(66,'Default: Expect wrapper','Expect wrapper','lfi','high','(?i)expect://','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(67,'Default: Windows UNC path inclusion','Windows UNC path inclusion','lfi','high','\\\\[^\\]+\\[^\\]+','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(68,'Default: Zip/rar archive inclusion','Zip/rar archive inclusion','lfi','high','(?i)zip://|rar://|com\.zip\|','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(69,'Default: Ogg wrapper / SSh2 / Zlib2','Ogg wrapper / SSh2 / Zlib2','lfi','high','(?i)(?:ogg|ssh2|zlib|rar)://','block',1,1,'2026-07-03 06:48:06');
INSERT INTO waf_custom_rules VALUES(70,'Default: PHP eval with base64_decode','PHP eval with base64_decode','webshell','critical','(?i)eval\s*\(\s*base64_decode','block',1,1,'2026-07-03 06:48:07');
INSERT INTO waf_custom_rules VALUES(71,'Default: Shell execution functions','Shell execution functions','webshell','critical','(?i)(?:shell_exec|passthru|system|exec|popen|proc_open|pcntl_exec)\s*\(','block',1,1,'2026-07-03 06:48:07');
INSERT INTO waf_custom_rules VALUES(72,'Default: PHP assert with code','PHP assert with code','webshell','critical','(?i)assert\s*\(\s*[''\"]?(?:base64_decode|\$_|\$GLOBALS|file_get_contents)','block',1,1,'2026-07-03 06:48:07');
INSERT INTO waf_custom_rules VALUES(73,'Default: PHP create_function / preg_replace /e','PHP create_function / preg_replace /e','webshell','high','(?i)(?:create_function|preg_replace)\s*\(\s*[''\"].*[eE].*[''\"]','block',1,1,'2026-07-03 06:48:07');
